    ["再晚点通知我们维修工的话，恐怕要出命案。"] = "Если мы позже не оповестим обслуживающий персонал, боюсь, произойдет смертельный исход.",
    ["再来一杯！"] = "Ещё по одной!",
    ["再深一点，根才扎得稳！"] = "Глубже, чтобы корни могли укрепиться!",
    ["再等等吧，说不定今天就回来了。"] = "Подождем еще немного, может быть, он вернется сегодня.",
    ["再等等，万一另一个小丑又要表演呢……"] = "Подожди еще немного, а вдруг другой Клоун тоже будет выступать...",
    ["再糊100盒火柴盒，就能和斯林太太换2磅黑麦面包。"] = "Если я склею еще 100 спичечных коробков, то смогу обменять их у миссис Слин на 2 фунта ржаного хлеба.",
    ["再说一次！再说一次故事我就吃胡萝卜！"] = "Расскажи ещё раз! Расскажи сказку ещё разок, и я съем морковку!",
    ["再这样下去，说不定我会……"] = "Если так пойдет и дальше, возможно, я...",
    ["再陪我一会儿吧，就一会儿！"] = "Побудь со мной еще чуточку, ну совсем немного!",
    ["写点什么好呢…… 赞美睡莲仙女！"] = "Что мне написать... Слава Фее Водяной Лилии!",
    ["冥皇……冥皇……冥皇……"] = "Император Смерти... Император Смерти... Император Смерти...",
    ["冰淇淋！好吃又不贵的冰淇淋！"] = "Мороженое! Вкусное и недорогое мороженое!",
    ["冰湖！了不起的冰湖！让我为你吟诵诗歌——"] = "Ледяное озеро! Великолепное ледяное озеро! Позвольте мне прочитать вам стихотворение —",
    ["冲激，冲激，冲激！"] = "Заряжай, заряжай, заряжай!",
    ["况且，廷根有许多大学生，看完了还可以再卖给他们。"] = "Кроме того, в Тингене много студентов, и я могу продать им их после прочтения.",
    ["冷静不下来……我想回学校念书……"] = "Не могу успокоиться... Хочу вернуться в школу учиться...",
    ["凌晨前要把这堆废料全部运走，我的老天，这要干多久？"] = "Мне нужно перевезти весь этот лом до рассвета, боже мой, сколько времени это займет?",
    ["几番忏悔，试用墨水凝结思绪。"] = "После нескольких признаний я пытаюсь с помощью чернил сконцентрировать свои мысли.",
    ["凯撒大帝的威名，仍在心中延续。"] = "Величие императора Цезаря по-прежнему живет в моем сердце.",
    ["凶手难道是他？"] = "Может ли убийца быть им?",
    ["出售各地香料，干货，欢迎选购。"] = "Продажа специй и галантерейных товаров со всего мира, добро пожаловать на просмотр.",
    ["切，这就结束了？"] = "Пф-ф, и это всё?",
    ["刚下船的先生女士们！准备上船的老爷夫人们！走过路过不要错过！"] = "Господа и дамы, которые только что сошли! Лорды и леди готовятся к посадке! Не пропустите, проходя мимо!",
    ["刚出炉的烤土豆，秘制酱汁，味美价廉！"] = "Только из печи! Печёный картофель с фирменным соусом: вкусно и недорого!",
    ["刚刚的绅士是不是在看我，我就知道，我今天光彩夺目！"] = "Тот джентльмен только что смотрел на меня, правда? Я так и знала: сегодня я неотразима!",
    ["刚才的是科恩黎，不久前从文职人员转为了正式的值夜者。"] = "Это был Коэн, который недавно перешел с канцелярской должности на формальный «Ночной ястреб».",
    ["刚才这一轮还不够好……"] = "Последний раунд был недостаточно хорош...",
    ["刚贴上的海报又不见了！"] = "Плакат, который я только что повесил, снова исчез!",
    ["别催，我正在看呢！"] = "Не торопи меня, я ищу!",
    ["别再挠我的屁股！走开！"] = "Хватит царапать мой зад! Отвяжись!",
    ["别再错过，听明白的请给我掌声！"] = "Не пропустите снова, если вы понимаете, пожалуйста, аплодируйте мне!",
    ["别动，亲爱的，这个光线……完美！"] = "Не двигайся, дорогая, это освещение... идеальное!",
    ["别吃了……我看着都害怕……"] = "Хватит есть... Мне страшно просто смотреть...",
    ["别吵了！"] = "Перестаньте шуметь!",
    ["别吵了，再不写完作业，天就黑啦。"] = "Хватит спорить, если ты не закончишь домашнее задание, скоро стемнеет.",
    ["别害羞，{{小哥|姑娘}}，来加入我们吧！"] = "Не стесняйся, {{парень|девушка}}, присоединяйся к нам!",
    ["别想在这里制造麻烦，我会一直盯着你。"] = "Не думай о том, чтобы создать здесь проблемы, я буду наблюдать за тобой.",
    ["别打扰我摸鱼。"] = "Не беспокой меня, пока я расслабляюсь.",
    ["别抱怨了，是你非要和夕阳下的教堂合影的！"] = "Перестаньте жаловаться, это вы настояли на том, чтобы сфотографироваться с церковью на закате!",
    ["别担心了维亚，在小镇上能遇到什么危险啊！"] = "Не волнуйся, Вейя, с какой опасностью ты можешь столкнуться в этом маленьком городке!",
    ["别担心老兄，我会在下面扶稳的！"] = "Не бойся, дружище, я придержу снизу!",
    ["别挤，别挤！我要被挤成迪西馅饼了！"] = "Не дави, не дави! Меня втиснут в пирог Дайси!",
    ["别提了……昨天我看到有俩流浪汉躺在这两张椅子上……"] = "И не говори... Вчера я видел, как на этих стульях разлеглись двое бродяг...",
    ["别提了，为了清剿这些该死的水鬼，我已经加班好几天了！"] = "Не упоминай об этом, я несколько дней работал сверхурочно, чтобы избавиться от этих проклятых водных призраков!",
    ["别激动，你再考虑考虑。"] = "Не горячись, подумай еще раз.",
    ["别犯傻了，我们可不是一个老板。"] = "Не глупи, у нас другой начальник.",
    ["别看我。"] = "Не смотри на меня.",
    ["别管我……"] = "Оставь меня в покое...",
    ["别管那箱子了！"] = "Забудьте о коробке!",
    ["别糊弄我！我打听过了，你们都是同一家进货商！"] = "Не пытайся меня обмануть! Я поспрашивал, вы оба пользуетесь одним и тем же поставщиком!",
    ["别被他发现了！"] = "Не позволяй ему узнать!",
    ["别说了，杰克。我就应该多花点租外面的摊位的。"] = "Не упоминай об этом, Джек. Мне пришлось потратить больше, чтобы арендовать киоск на улице.",
    ["别说这个字……会被那个听到的。"] = "Не говори этого слова... его услышит тот.",
    ["别输给那帮人！你们是最棒的绿色闪电！"] = "Не проиграйте этим ребятам! Ты лучшая Зеленая Молния!",
    ["别逞强了，伙计，你鼻涕都粘在袖子上了。"] = "Хватит храбриться, приятель: ты уже все рукава соплями измазал.",
    ["别错过这场精彩的比赛，为霍伊大学加油吧！"] = "Не пропустите эту захватывающую гонку, болейте за Университет Хоуи!",
    ["别错过这款最新的老爷车！"] = "Не пропустите эту новейшую винтажную машину!",
    ["别问了，我怕我忍不住会告诉你。"] = "Не спрашивай, боюсь, я не смогу удержаться от того, чтобы сказать тебе.",
    ["别闹了亲爱的，这么多人看着呢，我们回家吧……"] = "Перестань, дорогая, столько людей смотрит, пойдём домой...",
    ["别靠近这些箱子……"] = "Не приближайтесь к этим коробкам...",
    ["到了，这就是查尼斯门，队长就在旁边的值班室。"] = "Мы здесь. Это Врата Чаниса. Капитан находится в соседней дежурной комнате.",
    ["到哪再去招个靠谱的主厨过来？"] = "Где найти другого надежного шеф-повара?",
    ["到底为什么路上一个垃圾桶都找不到啊？！"] = "Почему на дороге нигде нет ни одной мусорки?!",
    ["到底什么时候开票啊！"] = "Когда билеты поступят в продажу!",
    ["到时候我就能天天站在甲板上看大海看个够了！"] = "К тому времени я смогу стоять на палубе и смотреть на море в свое удовольствие каждый день!",
    ["前天是潮汐问题。潮汐，懂吗？不稳定的水流会影响鱼获……"] = "Позавчера случился прилив. Приливы, понимаешь? Нестабильные течения воды влияют на улов...",
    ["前天，斗邪恶。昨天，斗邪恶。今天，斗邪恶。"] = "Позавчера борьба со злом. Вчера борьба со злом. Сегодня борьба со злом.",
    ["前方在休整，这条路过不去，{{先生|女士}}。"] = "Дорога впереди ремонтируется, здесь нельзя проехать, {{ Mr. | Ms. } }.",
    ["前方是私人空间， 未经邀请禁止入内。 "] = "Это личное пространство, вход без приглашения запрещен.",
    ["前调是香甜的香梨，中调是小苍兰、玫瑰，后调是琥珀的香气。"] = "Верхняя нота: сладкая груша, средняя нота: фрезия и роза, базовая нота: амбра.",
    ["前面就是廷根的著名景点，黑夜奉献碑！"] = "Впереди знаменитая достопримечательность Тингена — Монумент Вечной ночи!",
    ["剩下1便士，我去斯林太太那。"] = "Остался 1 пенс, я иду к миссис Слин.",
    ["加油呀！"] = "Действуй!",
    ["加油约翰，只要叼住一块面包就行了！"] = "Давай, Джон, просто откуси кусок хлеба!",
    ["加油！加油！"] = "Идти! Идти!",
    ["动物表演？真残忍啊。"] = "Дрессированные животные? Какая жестокость.",
    ["劳动才不会变成无赖……"] = "Труд не превратит тебя в мошенника...",
    ["劳驾，可否为我把这条矢车菊蓝的宝石项链包起？我要送给我的未婚妻。"] = "Извините, не могли бы вы упаковать мне это ожерелье с васильковыми камнями? Я хочу подарить его своей невесте.",
    ["劳驾，请帮我把这条矢车菊蓝的宝石项链包起来，我要送给我的未婚妻。"] = "Извините, пожалуйста, помогите мне завернуть это ожерелье с васильково-синим драгоценным камнем; Я хочу подарить его своей невесте.",
    ["勇敢的少年，追随大帝的脚步寻找真理。"] = "Храбрый юноша, иди по стопам Императора в поисках истины.",
    ["勇者拔剑，恶龙怒吼，故事无法干预 。"] = "Герой обнажает меч, дракон издает рев, в историю нельзя вмешиваться.",
    ["区区……呕……区区大海的波动，怎能比得上股市的线条起伏，呕——"] = "Всего лишь... *урп*... простые колебания моря, как они могут сравниться с линиями фондового рынка, *урп*—",
    ["医生！我……"] = "Доктор! Я...",
    ["医生，您看看那女孩吧！"] = "Доктор, пожалуйста, взгляните на эту девушку!",
    ["医生，您这衣服……"] = "Доктор, ваша одежда...",
    ["十个小时的历史讲座？这老头疯了吧？"] = "Десять часов лекций по истории? Этот старик сумасшедший?",
    ["十几年了，还这么干劲十足啊。"] = "Прошло уже более десяти лет, а он все еще полон энергии.",
    ["十几种蔬菜任您挑选！"] = "Более десятка видов овощей на ваш выбор!",
    ["十年前，我还只是一个穷学生，谁能想到今天我能走到这个高度？哼……"] = "Десять лет назад я был всего лишь нищим студентом... Кто мог подумать, что сегодня я поднимусь на такую высоту? Хм...",
    ["十年没回去了，一切是不是都变样了？"] = "Прошло десять лет с тех пор, как я вернулся, все изменилось?",
    ["十磅？你说得轻易，你这该死的黑心肠的家伙！"] = "Десять фунтов? Тебе легко говорить, проклятый ты бессердечный негодяй!",
    ["半年……我的女神啊。"] = "Полгода... моя Богиня.",
    ["卖不出货，就没钱，没钱我们就只能待在这里！"] = "Если мы не сможем ничего продать, у нас нет денег, а если у нас нет денег, мы застрянем здесь!",
    ["卖伞喽，晴天2苏勒，雨天1苏勒！"] = "Продаются зонтики, 2 суле в солнечные дни, 1 соло в дождливые дни!",
    ["卖报卖报！《廷根市老实人报》！《塔索克报》！"] = "Дополнительный! Дополнительный! Прочитать все об этом! Тинген, честный человек! Тассок Таймс!",
    ["卖报！卖报！"] = "Дополнительный! Дополнительный! Прочитать все об этом!",
    ["卖掉。买家我已经找好了，韦尔奇。"] = "Продайте это. Я уже нашел покупателя, Уэлч.",
    ["南大陆新品种辣椒，绝对辣到哭！"] = "Новый сорт чили с Южного континента, настолько острый, что заставит вас плакать!",
    ["南征北战，迎接神谕，新航道的开辟。"] = "Покорение юга и севера, приветствие оракула, открытие нового маршрута.",
    ["南边大水决了堤，北边弹弓满天飞。"] = "Великое наводнение прорвало дамбу на юге, а на севере повсюду летают рогатки.",
    ["占位"] = "Инфо",
    ["占卜家真方便，有不知道的就占一下。"] = "Провидец действительно удобен; если есть что-то, чего ты не знаешь, ты просто угадываешь это.",
    ["占卜解决不了任何事情，只是征兆。"] = "Гадание ничего не может решить; это просто знак.",
    ["占坑"] = "Инфо",
    ["卡伦，何必为一个平民女孩伤神，以你的身份，肯定有更好的人选。"] = "Каллен, зачем беспокоиться о простой девушке? С вашим статусом должны быть кандидаты получше.",
    ["卡伦，你已经在这里站了二十分钟了。"] = "Карен, ты стоишь здесь уже целых двадцать минут.",
    ["卡森前天就没来上工了，不会是他吧？"] = "Карсон не пришел на работу позавчера, может это был он?",
    ["卢卡今天会回来吗……"] = "Вернется ли Лука сегодня...",
    ["卢瑟那个白痴到底什么时候出来？"] = "Когда же выйдет этот идиот Лютер?",
    ["即日起，警署将严查酒驾，绝不姑息！"] = "С сегодняшнего дня полицейское управление будет строго расследовать вождение в нетрезвом виде и никогда не будет снисходительным!",
    ["厂里发的衣服薄得像厕纸！火星溅上来，直接烧穿我裤裆！"] = "Одежда, выпускаемая фабрикой, тонкая, как туалетная бумага! Искры взлетают и прожигают мне промежность!",
    ["厂里，还欠我一个月薪水……"] = "Завод до сих пор мне должен зарплату за месяц...",
    ["厄难与恐惧的女皇，安眠和寂静的领主。"] = "Императрица Бедствий и Ужасов, Госпожа Сна и Тишины.",
    ["原来如此……"] = "Так вот оно как...",
    ["原来是这样……安提哥努斯家族……"] = "Вот так оно и есть... семья Антигона...",
    ["原来量尺寸要这么久吗？"] = "Неужели измерения занимают так много времени?",
    ["去他的鳟鱼！全被工厂毒水腌成咸鱼干了……"] = "К черту форель! Всех их замариновали в ядовитой заводской воде и превратили в сушеную соленую рыбу...",
    ["去看抓老鼠？我觉得那条新狗不错……"] = "Пойти посмотреть ловлю крыс? Я думаю, что новая собака довольно хороша...",
    ["去贝克兰德，亲爱的，去贝克兰德大学你哥哥那里。"] = "Отправляйся в Бэкланд, моя дорогая, отправляйся к своему брату в Баклундский университет.",
    ["参与一下吧，你绝对能从这个家伙手里赢到钱！"] = "Присоединяйтесь, вы точно сможете выиграть деньги у этого парня!",
    ["又一封追求者的来信……嗯？这一封我没拆过吗？"] = "Еще одно письмо от жениха... хм? Разве я не открывал это?",
    ["又不是要参加舞会，素一点才合适嘛。"] = "Мы же не на бал собрались, так что лучше одеться поскромнее.",
    ["又临时有事？！多少次了，我要和你分手！"] = "Опять неотложные дела?! Сколько можно, я ухожу от тебя!",
    ["又在斗邪恶？你们完全不工作吗？"] = "Опять бороться со злом? Ребята, вы вообще не работаете?",
    ["又是划船，这都第八次了。"] = "Снова катаемся на лодке, уже в восьмой раз.",
    ["又有新的客人过来了……呼呼……\n奇怪呀……村里说过，不能偷偷摸摸做事的……"] = "Приходят новые гости... Хуху... \n Странно... В деревне говорят, что тайно ничего делать нельзя...",
    ["又来一个小丑？这才有点看头！"] = "Еще один клоун? Вот это стоит посмотреть!",
    ["又给克利夫这家伙跑掉了！"] = "Клифф, этот парень снова сбежал!",
