    ["夫人，应该先找酒店入住……"] = "Мадам, сначала нам нужно найти отель, чтобы заселиться...",
    ["夫人，我们把亚瑟带回来了。"] = "Мэм, мы вернули Артура.",
    ["夫人，据说德维尔爵士也要和您一起参与下一届的市长竞选。"] = "Миледи, говорят, что лорд Дервал также будет участвовать с вами в следующих выборах мэра.",
    ["夫人，笑容再灿烂一些！没错，就是那样！"] = "Сударыня, улыбнитесь чуть лучезарнее! Вот так, именно так!",
    ["夫人，这款午夜玫瑰听起来很浪漫。"] = "Миледи, эта Полуночная Роза звучит очень романтично.",
    ["夫人，这礼服是否太过……艳丽？"] = "Миледи, возможно, это платье слишком... яркое?",
    ["失业可能在明天，也可能在今天……"] = "Безработица может наступить завтра, а может наступить сегодня...",
    ["奇怪……到底丢到哪里去了？"] = "Странно... Куда же я это дел?",
    ["奇怪……放到哪里了……"] = "Странно... Куда я это положил...",
    ["奇怪，妈妈明明说了不会有人拒绝我的……"] = "Странно, мама четко сказала, что мне никто не откажет...",
    ["奈拉小姐同款香水！只要二十苏勒！"] = "Те же духи, что у мисс Найлы! Всего двадцать солей!",
    ["奈拉小姐的调香手艺究竟是跟谁学的呢？"] = "У кого именно мисс Наиля училась своему парфюмерному мастерству?",
    ["奈拉小姐肯定很生气吧？她没有来找妮基的麻烦？"] = "Мисс Найла, наверное, очень зла? Она не приходила досаждать Ники?",
    ["奈拉小姐说，\"他只是来闻一闻旧事\"……这位先生一定有难以忘却的记忆吧。"] = "Мисс Наиля говорит: «Он здесь только для того, чтобы учуять запах прошлого»... У этого джентльмена, должно быть, есть незабываемые воспоминания.",
    ["奈拉小姐，您的香水只有我新购入的联排别墅才配得上！只要您点点头，香水价格随您开。"] = "Мисс Наиля, ваши духи достойны только того таунхауса, который я только что купил! Пока вы киваете, вы можете назвать свою цену на духи.",
    ["奈拉小姐，我全要了——这整间店里的香水。"] = "Мисс Наиля, я возьму их все — все духи в этом магазине.",
    ["奈拉，白鸢尾在开春时最香，那封信应该已经送到你手上了吧？"] = "Найра, белые ирисы наиболее ароматны ранней весной. Это письмо уже должно было дойти до твоих рук, верно?",
    ["奢华、夺目、迷人的时代感和绝无仅有的体验……"] = "Роскошь, ослепительный блеск, пленительный дух эпохи и ни с чем не сравнимые впечатления...",
    ["奥尔登低头看书的侧脸也太帅了吧！睫毛好长…… 天呐！他抬眼了！是不是看到我了？赶紧假装学习，别让他发现我在偷看！ "] = "Профиль Олдена, когда он смотрит на книгу, просто слишком красив! Ресницы у него такие длинные... Боже мой! Он посмотрел вверх! Он видел меня? Быстро притворись, что учишься, не дай ему узнать, что я подсматриваю!",
    ["奥尔逊，你认识这两个字吗？"] = "Олсон, ты знаешь эти два слова?",
    ["女士们先生们，欢迎各位登上“万都之都”号。"] = "Дамы и господа, добро пожаловать на борт «Столицы столиц».",
    ["女士们先生们，能否占用你一分钟时间？"] = "Дамы и господа, могу я занять минутку вашего времени?",
    ["女士们！先生们！"] = "Дамы! Господа!",
    ["女士们，先生们！请您停下脚步看一看吧！"] = "Дамы и господа! Пожалуйста, остановитесь и посмотрите!",
    ["女士们，我……"] = "Дамы, я...",
    ["女士请拿好您的两张票。"] = "Пожалуйста, возьмите два билета, мадам.",
    ["女士，您消消气。我会向市长反馈的。"] = "Мадам, пожалуйста, успокойтесь. Я предоставлю отзыв мэру.",
    ["女士，我不能以这个价卖掉我的花！"] = "Мадам, я не могу продать свои цветы по такой цене!",
    ["女性应该把父亲和丈夫的话作为第一准则。"] = "Женщины должны принимать слова своего отца и мужа как главный принцип.",
    ["女神也会允许我这样说明，因为那实在扰乱我的心境……"] = "Богиня позволила мне объяснить это именно так, потому что это действительно тревожит мое душевное состояние...",
    ["女神会原谅我吗……会的吧！"] = "Простит ли меня Богиня... она простит, да!",
    ["女神保佑……总不至于有这样大胆的恶鬼，敢在教堂附近作怪。"] = "Богиня, храни нас... Не может быть, чтобы столь дерзкий злой дух осмелился бесчинствовать возле церкви.",
    ["女神保佑……这种话可别乱说。"] = "Благослови Богиня... не говори такие вещи.",
    ["女神啊……你已经考虑十分钟了。"] = "О, Богиня... ты обдумывала это уже десять минут.",
    ["女神啊！你不要伸手！小心摔下来！"] = "Богиня праведная! Не тянись руками! Упадешь ведь!",
    ["女神啊！菲尔，你怎么爬上去的？"] = "О, Богиня! Фил, как ты туда забрался?",
    ["女神啊！食堂的面包能当凶器！ "] = "О Богиня! Хлебом из столовой можно убить человека! ",
    ["女神啊，你能不能先好好工作！"] = "О Богиня, пожалуйста, делай свою работу как следует!",
    ["女神啊，占卜师现在也是高危职业吗……我情愿报纸上多刊登些填字游戏，也不想看见这个……"] = "Богиня, неужели гадалки теперь являются высокорискованной профессией... Я лучше опубликую в газетах больше кроссвордов, чем увижу это...",
    ["女神啊，好歹让我洗完衣服再停水啊……"] = "О Богиня, дай мне хотя бы закончить стирку, прежде чем ты выключишь воду...",
    ["女神啊，我以为是无聊的谣传呢。"] = "Богиня, я думал, что это просто скучный слух.",
    ["女神啊，我愿把全部的柔情都铺垫在她脚边！"] = "Богиня, я готов положить к ее ногам всю свою нежность!",
    ["女神啊，我有选择困难症……"] = "Богиня, у меня паралич решений...",
    ["女神啊，我能否将你比作一个夏日？"] = "Богиня, могу ли я сравнить тебя с летним днем?",
    ["女神啊，我该怎么办……？"] = "Богиня, что мне делать...?",
    ["女神啊，祈求我在贝克兰德的求学之旅一路顺利。"] = "Богиня, молись, чтобы моя учеба в Баклунде прошла гладко.",
    ["女神啊，若你能够听到我的呼唤，让小艾琳回到我身边吧。"] = "Богиня, если ты слышишь мой зов, пусть маленькая Ирен вернется ко мне.",
    ["女神啊，请垂怜！"] = "О Богиня, пожалуйста, помилуй!",
    ["女神啊，请让天上掉迪西馅饼吧——"] = "О Богиня, пусть с неба посыплются десийские пироги!..",
    ["女神啊，这些话语如同泉水一般在我的脑海中延绵不绝！"] = "О Богиня, эти слова бьют ключом в моей голове, и нет им конца!",
    ["女神啊，这已经是第三块了！"] = "О Богиня, это уже третья часть!",
    ["女神在上……可真吓人……"] = "Богиня сверху... это действительно страшно...",
    ["女神在上，只有这世道变好，才能给她一个家"] = "Богиня свидетельница, только если этот мир станет лучше, я смогу дать ей настоящий дом.",
    ["女神将一个礼物赐给我。"] = "Богиня даровала мне подарок.",
    ["女神庇佑啊……"] = "Да защитит Богиня...",
    ["女神庇佑我排到济贫院的名额，只要给我饭吃，我愿意挑绳絮。"] = "Пусть Богиня благословит меня местом в богадельне. Пока у меня есть еда, я готов собирать волокна веревки.",
    ["女神庇佑，请赐予我的爱人一夜安眠吧，呵呵。"] = "Благослови меня Богиня, пожалуйста, дайте моему возлюбленному хорошо выспаться, ха-ха.",
    ["奶奶！您在天堂还好吗，有见到爷爷吗？"] = "Бабушка! У тебя все хорошо на небесах? Ты видел дедушку?",
    ["奶奶，那边又在吵架……"] = "Бабушка, они там опять ссорятся...",
    ["她丈夫这么久了还没回来，不会是……"] = "Ее мужа так долго нет, неужели он...",
    ["她今天美得像夜晚的星辉……"] = "Сегодня она прекрасна, точно сияние ночных звезд...",
    ["她从哪儿来的？"] = "Откуда она взялась?",
    ["她以前很喜欢来这里，能挑上一整个下午。只是我当时太年轻，没有耐心等待……"] = "Раньше она любила приходить сюда и могла потратить целый день, выбирая одно из них. Просто я тогда был слишком молод и не хватило терпения ждать...",
    ["她大概到我腰这么高，金头发，有一双漂亮的大眼睛。"] = "Она ростом примерно с мою талию, у нее золотистые волосы и красивые большие глаза.",
    ["她家就在旁边这栋楼上吧？"] = "Ее дом находится в соседнем здании, верно?",
    ["她怎么每天都站在这里看船，脖子上还戴着那条项链。"] = "Почему она стоит здесь каждый день, наблюдая за кораблями, с этим ожерельем на шее?",
    ["她拒绝我的时候，神情很平静，连一句客套话都没有……"] = "Когда она мне отказала, выражение ее лица было очень спокойное, даже без вежливой фразы...",
    ["她来码头接她的丈夫。"] = "Она пришла на пристань, чтобы забрать мужа.",
    ["她没有说客套话，是不是就代表我在她心里并不一般……"] = "Если она не сказала ничего вежливого, значит ли это, что я для нее не просто кто-то...",
    ["她的离开让我的心都碎了。人活着的意义到底是什么？"] = "Ее уход разбил мне сердце. В чем смысл быть живым?",
    ["她真的好美啊……而且那些香水，闻起来确实不一样，她最后究竟会接受哪位伯爵呢？"] = "Она действительно такая красивая... и эти духи действительно пахнут по-другому. Какого графа она в конце концов примет?",
    ["她确实有登门拜访。不过比起生气，她看上去更像是在哀伤。"] = "Она действительно приходила. Но выглядела скорее скорбящей, чем сердитой.",
    ["她肯定是爱上我了……才会对我说这么多自己家里的事。"] = "Должно быть, она в меня влюбилась... поэтому так много рассказала мне о своей семье.",
    ["她说只要一束红玫瑰，她就愿意和我去跳舞……"] = "Она сказала, что если я подарю ей букет красных роз, она согласится пойти со мной на танцы...",
    ["她说：\"果然不是她。\""] = "Она сказала: «Так и думала, это не она».",
    ["好不容易全家来大城市，必须拍个全家福。"] = "Нелегко всей семьей приехать в большой город, надо сделать семейное фото.",
    ["好主意！粉色做成长裙，鹅黄色就做成花苞裙……"] = "Хорошая идея! Я сделаю из розового длинное платье, а из гусино-желтого — юбку-тюльпан...",
    ["好久没有这种一见钟情的感觉了，好开心啊。"] = "Давно я не чувствовал такой любви с первого взгляда, такой счастливой.",
    ["好你个玛莎，我们合作这么久，你居然背着我在账上做手脚！"] = "Ты, Марта, мы так долго работаем вместе, а ты фактически готовишь книги за моей спиной!",
    ["好冷……"] = "Так холодно...",
    ["好吧好吧，小镇建立时，有一位睡莲仙女……"] = "Ладно-ладно, когда был основан Маленький Городок, там жила Фея Водяных Лилий...",
    ["好吧，好吧，我听你们的。"] = "Ладно, ладно, я послушаю вас.",
    ["好吧，我们已经比那些工厂里的工人好很多了。"] = "Что ж, нам живется куда лучше, чем фабричным рабочим.",
    ["好吧，梅丽莎，你偶尔可以……"] = "Хорошо, Мелисса, иногда ты можешь...",
    ["好吧，那个确实了不起。"] = "Что ж, это и правда впечатляет.",
    ["好啦！都吵什么呢，我们都是一家人！"] = "Хорошо! О чем вы все спорите? Мы все одна семья!",
    ["好啦，不要吵了，我们给它取个名字怎么样？"] = "Ну хватит спорить, давайте дадим ему имя?",
    ["好喜欢橱窗里那些精致漂亮的玩偶。"] = "Мне очень нравятся эти изысканные и красивые куклы на витрине.",
    ["好困……"] = "Такой сонный...",
    ["好多复杂的细节数据……"] = "Столько сложных детальных данных...",
    ["好大的风啊！我的脸都要被吹痛了。"] = "Какой сильный ветер! Мое лицо начинает болеть от дуновения.",
    ["好奇心会害死猫的，莉莉。"] = "Любопытство убило кошку Лили.",
    ["好好工作，别瞎想了，我会一直把你当最好的朋友。"] = "Работай усердно, перестань думать глупости, я всегда буду относиться к тебе как к своему лучшему другу.",
    ["好心人，给点零钱吧……"] = "Добрая душа, пожалей немного мелочи...",
    ["好想变成大人啊……"] = "Я очень хочу стать взрослой...",
    ["好想吃……"] = "Я очень хочу это съесть...",
    ["好想有人帮我一起除草……"] = "Вот бы кто-нибудь помог мне прополоть сорняки...",
    ["好想玩……"] = "Так хочется поиграть...",
    ["好报纸，最新鲜，日期肯定是今天！"] = "Хорошая газета, свежайшая, дата должна быть сегодняшняя!",
    ["好晕，怎么更难受了？"] = "Так кружится голова... почему стало ещё хуже?",
    ["好期待今天的神秘动物表演啊！"] = "Я так жду сегодняшнего представления загадочных животных!",
    ["好期待晚上他看见这个惊喜时的神情了……"] = "Я так жду выражения его лица, когда он сегодня вечером увидит этот сюрприз...",
    ["好气派的车！"] = "Какая роскошная карета!",
    ["好漂亮的鱼！"] = "Какая красивая рыбка!",
    ["好焦虑，想到不上班没收入，我就头晕、眼花、拉肚子。"] = "Я так беспокоюсь, что мысли о том, что у меня не будет дохода, если я не буду работать, вызывают у меня головокружение, легкомысленность и диарею.",
    ["好焦虑，想到要去上班，我就胸闷、气短、腿抽筋。"] = "Я так волнуюсь. Когда я думаю о том, чтобы пойти на работу, я чувствую стеснение в груди, одышку и судороги в ногах.",
    ["好痛……"] = "Это больно...",
    ["好的……"] = "Хорошо...",
    ["好的……能以朋友的身份陪伴你，我也心满意足了。"] = "Хорошо... Я доволен тем, что могу сопровождать тебя как друг.",
    ["好的……需要我帮您……给黑猫大人戴上吗？"] = "Хорошо... Вам помочь... надеть это на господина Черного Кота?",
    ["好的股票主理人，不需要主动推销。"] = "Хорошему управляющему запасами не нужно активно продвигать товар.",
    ["好的，麻烦你了。"] = "Хорошо, спасибо за труды.",
    ["好累……想要什么鱼自己挑吧。"] = "Так устал... Бери любую рыбу, какую хочешь.",
    ["好花酿好酒！全镇最清新的口感！"] = "Из хороших цветов получается хорошее вино! Самый свежий вкус в городе!",
    ["好饿……好困……"] = "Такой голодный... такой сонный...",
    ["好饿。"] = "Такой голодный.",
    ["好饿，爸爸最近很晚才回家，房东先生又来催房租了。"] = "Я так голоден. В последнее время папа приходил домой очень поздно, и домовладелец снова здесь, чтобы потребовать арендную плату.",
    ["好香……马上就煮好了……"] = "Так вкусно пахнет... скоро будет готово...",
    ["好香的茶……"] = "Какой ароматный чай...",
    ["好，下一位！"] = "Хорошо, следующий!",
    ["好，再来一遍!"] = "Хорошо, давай повторим!",
    ["好，就深蓝色吧。"] = "Хорошо, давайте возьмем темно-синий.",
    ["好，我们回去吧。"] = "Хорошо, давайте вернемся.",
    ["好，我去找找看。"] = "Хорошо, я пойду искать.",
    ["好，我多采一点。"] = "Хорошо, я выберу еще несколько.",
    ["好，那我一定好好学习！"] = "Хорошо, тогда я обязательно буду усердно учиться!",
    ["如您需要交易，请领取文件并安排公证服务。"] = "Если вам нужно торговать, пожалуйста, соберите документы и оформите нотариальное заверение.",
    ["如果不想铁十字街的事重演，就把你的心，变得无坚不摧。"] = "Если не хотите повторения случившегося на улице Железного Креста, сделайте своё сердце несокрушимым.",
    ["如果人类能停止新陈代谢就好了，如果我能停止存在就好了。"] = "Если бы только люди могли прекратить обмен веществ, если бы я мог перестать существовать.",
    ["如果你临时缺钱，可以来找我。"] = "Если у вас мало денег, вы можете прийти ко мне.",
    ["如果你想得知真相，经过时间验证的旧东西远好于新东西。"] = "Если хочешь узнать правду, проверенное временем старое куда лучше нового.",
    ["如果你想追寻新奇，罗赛尔大帝曾经说过：“太阳底下没有新鲜事。”"] = "Если ищете новизны, император Розель однажды сказал: «Нет ничего нового под Солнцем».",
    ["如果你成为了政府处理具体事务的雇员，我们的家庭收入会增加多少？"] = "Если вы станете государственным служащим, занимающимся конкретными делами, насколько увеличится доход нашей семьи?",
    ["如果在这山中见到他，请您一定劝他回来……"] = "Если вы увидите его в этих горах, пожалуйста, уговорите его вернуться...",
    ["如果坏人都死了，这个世界就会更美好吧……"] = "Если бы все плохие парни умерли, мир стал бы лучше...",
    ["如果她能放下，这项链在哪也无所谓了吧……"] = "Если бы она могла отпустить, не имело бы значения, где находится ожерелье...",
    ["如果您只有一个小箱子，1便士就够了。"] = "Если у вас только небольшой чемодан, достаточно 1 пенс.",
    ["如果您愿意，请支持我们少爷所在的红色队伍！"] = "Если хотите, поддержите красную команду, в которой находится наш молодой мастер!",
    ["如果您手里有“特殊来源”的货品，也可以交给我寄售。"] = "Если у вас есть товары «особого происхождения», можете передать их мне на комиссию.",
    ["如果我死了，会有人在这些长椅上纪念我吗？"] = "Если я умру, будет ли кто-нибудь почтить меня на этих скамейках?",
    ["如果政府真的决定通过考试来选拔官员，这些付出都是值得的。"] = "Если правительство действительно решит отбирать чиновников посредством экзаменов, эти усилия будут того стоить.",
    ["如果桶里的酒喝不完，我是不是也长不大？"] = "Если я не смогу допить вино в бочке, я тоже не вырасту?",
    ["如果每个人再少发点工资，工厂成本就能再少些……"] = "Если бы всем снизить заработную плату еще немного, производственные затраты могли бы сократиться еще больше...",
    ["如果每位小绅士都像您这么悠闲……"] = "Если бы все юные джентльмены вели такую же праздную жизнь, как вы...",
    ["如果能搞到《所罗门皇帝》的票，珍妮斯一定会答应我的邀约的！"] = "Если я смогу достать билет на «Императора Соломона», Дженис обязательно примет мое приглашение!",
    ["如果见不到明天的夜晚，请女神眷顾我的家人一切平安。"] = "Если я не увижу завтрашнюю ночь, пожалуйста, пусть Богиня благословит мою семью миром.",
    ["如果需要，也可以找我特别定制。"] = "Если вам нужно, вы также можете попросить меня настроить его для вас.",
    ["如遇到危险，请及时求助，守卫们将尽全力保障您的安全。"] = "Если вы столкнулись с опасностью, пожалуйста, вовремя обратитесь за помощью, и охрана сделает все возможное, чтобы обеспечить вашу безопасность.",
    ["妈妈……"] = "Мама...",
    ["妈妈快来，就等你了！"] = "Мама, поторопись, мы только тебя ждем!",
    ["妈妈怎么还不出来……"] = "Почему мама еще не вышла...",
    ["妈妈是因为爸爸抽烟生气的！"] = "Мама злится, потому что папа курит!",
    ["妈妈爸爸，牵住我的手！"] = "Мама, папа, держите меня за руки!",
    ["妈妈说女孩子一定要拥有自己的表，可没说表这么贵……"] = "Мать говорила, что у девочки должны быть свои часы, но она не говорила, что часы такие дорогие...",
    ["妈妈说攒够钱就送我去学画画，希望客人们多买点……"] = "Мама сказала, что отправит меня учиться рисовать, как только накопит достаточно денег. Я надеюсь, что клиенты будут покупать больше...",
    ["妈妈，我们要去哪里？"] = "Мама, куда мы идем?",
    ["妈妈，我好想你。"] = "Мама, я так скучаю по тебе.",
    ["妈妈，我考上廷根大学了，爸爸和弟弟他们都很开心。"] = "Мам, я поступил в университет Тинген. Папа и мой младший брат оба очень счастливы.",
    ["妈妈，爸爸会在下一辆车上吗？"] = "Мама, а папа будет в следующем вагоне?",
    ["妈妈，让我去吧……"] = "Мама, отпусти меня...",
    ["妈妈，请入我梦来。"] = "Мама, пожалуйста, войди в мои сны.",
    ["姐姐，这个消息，我只跟你说，你别外传。"] = "Сестра, я только сообщаю тебе эту новость, не разглашай ее.",
    ["姓名？住址？职业？"] = "Имя? адрес? Профессия?",
    ["威尔伯，你快下来！"] = "Уилбур, спускайся быстрее!",
    ["子弹又用完了，得再去报销一次。"] = "Патроны опять закончились, надо снова подавать на компенсацию.",
    ["学费还是有点贵啊。"] = "Стоимость обучения все еще немного дорогая.",
    ["孩子们,知道今天为什么要带你们来拜访牺牲的战士吗？"] = "Дети, знаете ли вы, почему я привел вас сегодня сюда, чтобы навестить павших воинов?",
    ["孩子们！休息一会！本杰明，你的生日面包来了，最大的那块！"] = "Дети! Передохните! Бенджамин, твой праздничный хлеб пришёл, самый большой кусок!",
    ["孩子们，背对终点的下一步是拥抱胜利。"] = "Дети, шаг после поворота спиной к финишу – это принятие Победы.",
    ["孩子，不管你的队伍有没有获得冠军，妈妈都支持你！"] = "Дитя, неважно, выиграет твоя команда чемпионат или нет, мама тебя поддерживает!",
    ["它不会理你的。"] = "Оно не обратит на вас внимания.",
    ["它不理你，是不喜欢这个名字吗？"] = "Оно тебя игнорирует, ему не нравится это имя?",
    ["它们曾经是什么？我……又是什么？"] = "Какими они были когда-то? И... кто я?",
    ["它会从礼帽里拉出人类吗？"] = "Вытащит ли он человека из цилиндра?",
    ["它在睡觉呢！"] = "Оно спит!",
    ["它就在这块地正下方，等它自己出来吧。"] = "Оно прямо под этим куском земли, пусть само вылезет.",
    ["它是一只黑白猫，彼得。"] = "Это чёрно-белая кошка по имени Питер.",
    ["它用排水渠漂移过了五连发夹弯。"] = "Он дрейфовал через пять последовательных шпилей, используя дренажную канаву.",
    ["它的速度很快，我只看到车后面写着哈罗德百货。"] = "Это было очень быстро; Я видел только надпись «Универмаг Гарольд» на обороте.",
    ["它确实缺掉了一块。你可以裁下和缺口一样形状的纸片，贴上去帮它补全。"] = "Одного куска действительно не хватает. Вырежьте кусочек бумаги той же формы, что и пробел, и приклейте, чтобы восполнить недостающее.",
    ["安东尼！上啊！干死他！"] = "Энтони! Идти! Убей его!",
    ["安妮，你看这有只小猫，它叫什么名字？"] = "Энни, смотри, здесь есть котёнок, как его зовут?",
    ["安妮，你看这有只白黑猫！"] = "Энни, смотри, здесь чёрно-белая кошка!",
    ["安息吧……我的爱！"] = "Покойся с миром... моя любовь!",
    ["安息吧母亲，有我在，小杰克不会饿肚子的。"] = "Покойся с миром, мама, со мной маленький Джек не останется голодным.",
    ["安提哥努斯，霍纳奇斯主峰，献祭仪式……我们聊到的知识可真不少。"] = "Антигон, главная вершина Горнациса, ритуал жертвоприношения... знаний, которые мы обсуждали, действительно очень много.",
    ["安曼达纯露快用完了，还要再买些铁筷子草、槲寄生粉末……"] = "Гидрозоль амандина почти закончился, надо прикупить еще порошка чемерицы и омелы...",
    ["完了完了，剪歪了……千万别被西希姐看见。"] = "Все кончено, все кончено, я криво порезал... Я не должен позволить сестре Сиси увидеть это.",
    ["完了，一切都完了……"] = "Все кончено, все кончено...",
    ["完蛋了，我会被骂的……"] = "Все кончено, меня будут ругать...",
    ["宝贝，想不想坐这样的车去兜风？"] = "Детка, хочешь покататься на такой машине?",
    ["实验应该是这样的！"] = "Эксперимент должен быть таким!",
    ["客人，想要点什么？"] = "Клиент, чего бы ты хотел?",
    ["客人，要买什么？新鲜的罗勒，小樱桃萝卜，还是卷心菜？"] = "Клиент, что бы ты хотел купить? Свежий базилик, небольшая редиска или капуста?",
    ["害怕父亲不是正常的吗？"] = "Разве это не нормально – бояться своего отца?",
    ["宴会礼服、日常外套、定制马甲……您的需求我们都能实现！"] = "Банкетные платья, повседневные пальто, жилеты на заказ... Мы можем удовлетворить все ваши потребности!",
    ["家庭开支计划的前提是尊重男主人的意见。"] = "Основой плана семейного бюджета является уважение мнения хозяина.",
    ["家道中落才……"] = "Только после того, как ее семья развалилась...",
    ["对不起亲爱的，今天有不得不去的工作…"] = "Извини, дорогая, у меня есть работа, которую мне нужно выполнить сегодня...",
    ["对不起，我的宝贝，我的甜心，我的小百合……"] = "Прости, мое сокровище, моя возлюбленная, моя маленькая лилия...",
    ["对不起，爸爸……"] = "Прости, папа...",
    ["对不起，罗塞尔大帝。"] = "Мне очень жаль, император Розель.",
    ["对了，阿兹克先生。"] = "Кстати, господин Азик.",
    ["对对对！就是狗抓老鼠的比赛，我和你说，太精彩了！"] = "Да, да, да! Это соревнование по ловле собак и мышей. Скажу вам, это было зрелищно!",
    ["对对，等你努力考到贝克兰德，就肯定能见到她了。"] = "Да-да, как только вы хорошо поработаете и попадете в Бэкланд, вы обязательно сможете ее увидеть.",
    ["对的对的……"] = "Верно, верно...",
    ["对！就是这个角度！"] = "Да! Вот это угол!",
    ["对！就是这样！"] = "Да! Вот и все!",
    ["对！我记得！我只是……只是……"] = "Верно! Я помню! Я просто... я просто...",
    ["对，再往右边站点！完美的姿势！"] = "Да, встаньте немного правее! Идеальная поза!",
    ["对，当英雄，保护爸爸妈妈，保护老师和同学！"] = "Да, будь героем, защити маму и папу, защити моих учителей и одноклассников!",
    ["将……奉献予夜……"] = "Мы... предлагаем себя ночи...",
    ["将短暂的良宵，"] = "Эту короткую чудесную ночь",
    ["尊敬的睡莲仙女，请赐予我高贵的睡莲。"] = "Почтенная фея кувшинок, прошу, даруй мне благородную кувшинку.",
    ["尊敬的睡莲，望您倾听我的愿望……"] = "Уважаемая Водяная Лилия, надеюсь, вы прислушаетесь к моему пожеланию...",
    ["尊敬的阿兹克先生，我想向您请教……"] = "Уважаемый господин Азик, хотел бы попросить у Вас совета...",
    ["小丑登场，演出开始！"] = "Клоун выходит на сцену, представление начинается!",
    ["小兄弟，在你们这儿买表……能明天给钱吗？"] = "Братишка, если я куплю у тебя часы... могу ли я заплатить завтра?",
    ["小兄弟，在你们这儿买表……能赊账吗？"] = "Братец, а можно у вас купить часы... в долг?",
    ["小姐们，可以把我的椅子还给我吗……"] = "Дамы, не могли бы вы вернуть мне мой стул...",
    ["小姐请别动，我来给您抚平裙子的褶皱。"] = "Мисс, пожалуйста, не шевелитесь, позвольте разгладить складки на вашем платье.",
    ["小姐，你在和什么人说话？"] = "Мисс, с кем вы разговариваете?",
    ["小姐，能听见我说话吗？您看起来状态很差。"] = "Мисс, вы меня слышите? Вы выглядите очень плохо.",
    ["小子们，给我划起来。"] = "Парни, гребите живее!",
    ["小子！别擦汗了，把扳手递给我"] = "Ребенок! Перестань вытирать пот и дай мне гаечный ключ.",
    ["小子，你下半辈子的交通工具只会是担架。"] = "Парень, единственное транспортное средство, которым ты будешь пользоваться всю оставшуюся жизнь, это носилки.",
    ["小心点，虽然我经常走这里，但我还是害怕摔倒， 咕噜咕噜滚下去。"] = "Будьте осторожны, я хоть и часто здесь гуляю, но все равно боюсь споткнуться и скатиться, гулу гулу.",
    ["小托比，待会儿可要猛蹬你那两条腿啊！"] = "Маленький Тоби, тебе лучше покрутить педали этими двумя ногами позже!",
    ["小时候她就爱问，这些钢铁到底是怎么炼成的。"] = "Когда она была маленькой, она любила спрашивать, как очищают эту сталь.",
    ["小杰……我的孩子……"] = "Маленький Джей... дитя мое...",
    ["小猫……小猫……"] = "Котёнок... котёнок...",
    ["小猫小猫，你说我会有机会登上那艘船吗？"] = "Котенок, котенок, как ты думаешь, у меня будет шанс попасть на борт этого корабля?",
    ["小猫小猫，爸爸到底更喜欢他的学生还是更喜欢我呢？"] = "Котик, котик, кого папа любит больше: своих студентов или меня?",
    ["小猫！你快下来呀！"] = "Котёнок! Спускайся скорее!",
    ["小猫，你快下来呀小猫。"] = "Котёнок, спускайся скорее, котёнок.",
    ["小米勒的身体好些了，或许，是时候将贝克兰德提上日程……"] = "Здоровье маленького Миллера улучшилось. Возможно, пришло время включить Баклунда в повестку дня...",
    ["小维什通过了政府雇员统一考试，真为他高兴……"] = "Маленький Виш сдал единый экзамен для госслужащего, я так рада за него...",
    ["小艾琳……她去了一个很远很远的地方，晚点才回来。"] = "Малышка Ирен... она уехала очень-очень далеко и вернется нескоро.",
    ["小艾琳看见冰淇淋就不想走了，可家里现在……"] = "Маленькая Ирэн не хочет уходить, когда видит мороженое, но теперь дома...",
    ["小花儿……我的宝贝们，今天过得好吗？"] = "Цветочки... мои дорогие, как ваши дела сегодня?",
    ["小莱雅，记得微笑哦。"] = "Маленькая Лея, не забывай улыбаться.",
    ["小道消息…… "] = "Внутренний совок...",
    ["小雏菊，绿丁香，花虽小，却芬芳！"] = "Ромашки, зеленая сирень, цветочки маленькие, но ароматные!",
    ["小鸟你好！小花你好！"] = "Привет, маленькая птичка! Здравствуй, маленький цветочек!",
    ["小鸟小鸟在思考，思考新家在哪里。"] = "Маленькая птичка, маленькая птичка думает, думает о том, где ее новый дом.",
    ["小鸟小鸟流下泪，天空之下没有家。"] = "Птичка, птичка слезы льет — в целом мире дома нет.",
    ["少做梦了！喝酒吧，明天还得搬货呢。"] = "Хватит витать в облаках! Пей давай, завтра опять мешки таскать.",
    ["少废话！把头抬起来！"] = "Прекратите это дерьмо! Поднимите голову вверх!",
    ["少爷，恕我冒犯，您的音乐教师还在等您。"] = "Молодой господин, если можно, ваш учитель музыки все еще ждет вас.",
    ["少爷，真的不能再做宽松了，婚礼礼服要合身才体面。"] = "Молодой Мастер, это действительно не может быть ослаблено. Свадебный костюм должен быть приличным.",
    ["尝试借鉴这种运营模式，中产阶级们总是愿意为面子买单……"] = "Попробуйте извлечь уроки из этой бизнес-модели: средний класс всегда готов платить за лицо...",
    ["尤瑟夫……等等，尤瑟夫先生告假了，那我的面试官会是谁？"] = "Юсуф... Постойте, господин Юсуф взял отгул, так кто же будет проводить моё собеседование?",
    ["尤瑟夫大夫今天在吗？"] = "Доктор Юсуф сегодня на месте?",
    ["尤瑟夫诊所怎么还关着门？"] = "Почему клиника Юсефа всё ещё закрыта?",
    ["就以他为主人公，写一本《落魄拳王复仇记》怎么样？"] = "Как насчет того, чтобы написать книгу под названием «Месть неудачливого боксера» с ним в качестве главного героя?",
    ["就到这里吧，再说就危险了。"] = "Давайте остановимся здесь; будет опасно, если мы скажем еще что-нибудь.",
    ["就在今天，全廷根最最劲爆的消息将被我蹲守出来！！！"] = "Именно сегодня я выслежу самую сенсационную новость во всем Тингене!!!",
    ["就在这儿再待一会儿吧。"] = "Просто побудь здесь еще немного.",
    ["就好像卖面包的人会说面包是一顿午饭的基石。"] = "Это похоже на то, как будто кто-то, продающий хлеб, сказал бы, что хлеб — краеугольный камень обеда.",
    ["就是以后再也没有这么大的图书馆了……"] = "Просто такой большой библиотеки больше никогда не будет...",
    ["就算我站在面前，他们也想不到，我就是他们在找的人。"] = "Даже если бы я стоял прямо перед ними, они бы не догадались, что я тот человек, которого они ищут.",
    ["就这点水平还打什么拳击赛！"] = "С таким уровнем мастерства, зачем ты вообще участвуешь в соревнованиях по ударам!",
    ["就那家，奈拉小姐那里。那可不是谁都能进去做事的，她的眼光高着呢。"] = "Это тот самый дом мисс Наилы. Не каждый может там работать; у нее очень высокие стандарты.",
