    ["总感觉画歪了……"] = "Мне всегда кажется, что оно криво нарисовано...",
    ["总有那么几个笨蛋……"] = "Идиотов всегда найдется...",
    ["恭喜！但有时候眼前的“希望”，可能才是命运最大的玩笑……"] = "Поздравляем! Но порой «надежда» прямо перед глазами оказывается самой жестокой шуткой судьбы...",
    ["恭喜！你找到了正确的王座～"] = "Поздравляем! Вы нашли правильный трон~",
    ["恰到好处的味蕾刺激或许是新世界的大门钥匙。"] = "Идеально рассчитанная по времени стимуляция вкусовых рецепторов может стать ключом к новому миру.",
    ["恳请女神垂怜，让少爷的努力得到回报！"] = "Я умоляю Богиню о милосердии и пусть усилия молодого мастера будут вознаграждены!",
    ["您不必费心一瓶瓶地介绍，待会我就让仆人们来打包，送去我郊外新庄园。 "] = "Вам не нужно вводить их бутылочку за бутылочкой. Позже я прикажу своим слугам собрать их и отправить в мое новое поместье в пригороде.",
    ["您也不是，哎那可怎么办才好？"] = "Вы тоже нет? Ох, что же тогда делать?",
    ["您也不赖。"] = "Ты сам не плохой.",
    ["您也可以选择为廷根大学助威，但胜利必将属于霍伊大学。"] = "Вы также можете поболеть за Университет Тинген, но победа наверняка будет принадлежать Университету Хой.",
    ["您也来这儿坐坐？他们家的烘焙双人餐似乎有特价。"] = "Ты тоже здесь, чтобы посидеть немного? Кажется, их запеченная еда на двоих имеет специальную скидку.",
    ["您别这么说……"] = "Пожалуйста, не говори так...",
    ["您又是要给家里那樽雕像买首饰？"] = "Вы снова покупаете украшения для этой статуи дома?",
    ["您吃薯条的时候，请务必小心这些可恶的海鸥！"] = "Когда вы едите картошку фри, будьте осторожны с этими ненавистными чайками!",
    ["您好女士，需要我帮您参谋一下吗？"] = "Здравствуйте, мадам, хотите, я помогу вам кое-что выбрать?",
    ["您好，{{先生|女士}}，很高兴能见到您。想吃点什么？"] = "Здравствуйте, {{мистер|мисс}}, рад вас видеть. Что бы вы хотели съесть?",
    ["您好，{{先生|女士}}，欢迎来到俱乐部。"] = "Привет, {{sir|madam}}, добро пожаловать в клуб.",
    ["您好，您想要到哪去？"] = "Здравствуйте, куда бы вы хотели поехать?",
    ["您好，您有什么需要吗？"] = "Здравствуйте, могу я чем-то помочь?",
    ["您好，我叫奥莲卡，是廷根大学医学院毕业的……"] = "Здравствуйте, меня зовут Оленка, я выпускница медицинского факультета Тингенского университета...",
    ["您好，我是马蒂尼，是这儿的侍酒师。"] = "Здравствуйте, я Мартини, здешний сомелье.",
    ["您好，请问您是芬顿吗？我捡到了您的牙科病历。"] = "Здравствуйте, вы Фентон? Я нашёл вашу стоматологическую карту.",
    ["您好，请问有什么事吗？"] = "Здравствуйте, могу ли я вам чем-то помочь?",
    ["您好，这里是交易公证处。公证人索罗·卡特为您服务。"] = "Здравствуйте, это нотариальная контора. Нотариус Соло Картер к вашим услугам.",
    ["您想来上一杯今日特调吗？"] = "Не желаете бокал нашего особого напитка дня?",
    ["您想看的，这里应有尽有！首都大事！奇闻八卦！"] = "Все, что вы хотите увидеть, находится прямо здесь! Столичные новости! Странная сплетня!",
    ["您手上那枚，是不是柜台里的样品？"] = "Тот, что у вас в руках, — это образец с прилавка?",
    ["您手里这把伞，刚好和那一把一模一样。"] = "Зонт у вас в руке точь-в-точь такой же, как тот.",
    ["您是本质的化身！工匠的保护者！技术的光辉！"] = "Вы – воплощение сущности! Защитник ремесленников! Сияние технологий!",
    ["您本人比照片瘦一点。"] = "Вживую вы выглядите немного тоньше, чем на фото.",
    ["您来错地方了吧。"] = "Вы пришли не туда.",
    ["您的谈吐<P_Yellow>幽默又风趣</>。"] = "Ваша беседа <P_Yellow>юмористична и остроумна</>.",
    ["您的身姿比花儿更美，我们再拍一张！"] = "Твоя поза красивее цветов, давай возьмем еще одну!",
    ["您看看我手里的这把？"] = "Взгляните на ту, что у меня в руке?",
    ["您看看这本！"] = "Взгляните на это!",
    ["您知道吗？有灵魂的人可以在诗中找到知己……"] = "Вы знаете? Люди с душой могут найти родственную душу в поэзии...",
    ["您知道的，我还是关注着自己的名声，并不想让人觉得我实在不体恤下层百姓，是吗？"] = "Знаешь, я все еще забочусь о своей репутации и не хочу, чтобы люди думали, что я действительно бессострадателен к низшим классам, не так ли?",
    ["您绝对没见过这么脆嫩的卷心菜！"] = "Такой хрустящей и нежной капусты вы точно еще не видели!",
    ["您说得很对，她穿这个一定也好看。"] = "Вы совершенно правы, здесь она тоже будет хорошо смотреться.",
    ["您走得太突然了，孩子一直都希望来廷根和您一起过暑假。"] = "Ты ушел так внезапно. Ваш ребенок всегда хотел приехать в Тинген, чтобы провести с вами летние каникулы.",
    ["想不想开这样的车去拉姆德小镇？"] = "Хотите поехать на такой машине в Ламуд-Таун?",
    ["想不想给妈妈买一辆？"] = "Хотите купить такой для мамы?",
    ["想为谁献上一束花呢？女神会祝福你的。       "] = "Кому вы хотите подарить букет цветов? Богиня благословит вас.",
    ["想去舞蹈社，不过划艇社也挺有意思……"] = "Я хочу в танцевальный кружок, но и в гребной кружок тоже довольно интересно...",
    ["想当年我也和罗莎是一样的地位……这才过了几年，就没人要了。"] = "Когда-то у меня был такой же статус, как у Розы... прошло всего несколько лет, и теперь я никому не нужен.",
    ["想当年我盥洗室里的马桶，都是镶着金子和钻石的，现在……"] = "Раньше унитазы в моей туалетной комнате были инкрустированы золотом и бриллиантами, а теперь...",
    ["想必他们现在已经成家立业了吧，也可能早就把我忘了。"] = "Наверное, они уже обзавелись семьями, а может быть, они меня уже давно забыли.",
    ["想恋爱来这里，这儿什么样的都有！"] = "Хотите влюбиться? Идите сюда, у нас здесь самые разные люди!",
    ["想杀我……你们还不够资格！"] = "Ты хочешь меня убить... ты недостаточно квалифицирован!",
    ["想给廷根大学的家伙们点颜色瞧瞧吗？请支持我们霍伊大学赛艇队吧！"] = "Хотите кое-что показать этим ребятам из Университета Тинген? Пожалуйста, поддержите нашу команду по гребле Университета Хой!",
    ["想要什么自己拿。"] = "Берите все, что хотите.",
    ["想！它看起来太酷了！"] = "Хочу! Это выглядит так здорово!",
    ["想！等等，我只有八岁啊妈妈……"] = "Да! Подожди, мне всего восемь лет, мама...",
    ["想！那边可太适合开车了！"] = "Да! Это место идеально подходит для вождения!",
    ["愚昧的人，看看他可怜的样子，一看就是中风了。"] = "Глупец, поглядите на его жалкий вид — сразу видно, удар хватил.",
    ["感觉怎么样，小艾琳娜？还是很难受吗？"] = "Как ты себя чувствуешь, маленькая Елена? Тебе все еще больно?",
    ["感觉配锡伯红茶会很搭。"] = "Мне кажется, он хорошо сочетается с черным чаем Сибе.",
    ["感谢你们的付出，愿女神保佑廷根！"] = "Спасибо за вашу преданность делу, пусть Богиня благословит Тинген!",
    ["感谢你们！亚瑟在书信里提到过，你们是他可靠的战友。"] = "Спасибо вам! Артур писал в письмах, что вы его надёжные боевые товарищи.",
    ["感谢女神……"] = "Слава Богине...",
    ["感谢女神！只要能吃饱肚子，我愿意信仰任何东西。"] = "Слава Богине! Лишь бы набить живот — я готов верить во что угодно.",
    ["感谢女神，让我和妹妹说服了爸爸，可以去上学啦！"] = "Слава Богине, мы с сестрой убедили папу, что теперь мы можем идти в школу!",
    ["感谢您。我是想给女儿挑一匹做礼服裙的料子，这匹米白薄缎最合适，就是……价格有些昂贵。"] = "Спасибо. Ищу ткань для пошива платья для дочери. Этот тонкий сатин кремового цвета самый подходящий, просто... цена немного дороговата.",
    ["感谢您所作出的努力，他度过了一段短暂但快乐的退休生涯。"] = "Спасибо за ваши усилия. Он провел короткую, но счастливую пенсию.",
    ["感谢您，伟大的风暴之主！"] = "Спасибо тебе, великий Повелитель Штормов!",
    ["愿圣者的意志与你我同在。"] = "Да пребудет воля Святого с тобой и со мной.",
    ["愿女神庇佑你！"] = "Да хранит тебя Богиня!",
    ["愿女神庇佑廷根，保佑廷根脱离邪恶的沾染，于厄难的缠绕中幸存。"] = "Пусть Богиня защитит Тинген, защитит Тинген от заражения злом и поможет ему пережить запутанную катастрофу.",
    ["愿女神庇佑您，夫人。"] = "Да благословит вас Богиня, мадам.",
    ["愿女神庇佑我们家平安……"] = "Пусть Богиня сохранит мир нашей семьи...",
    ["愿女神庇佑我可怜的小艾琳娜远离灾厄，能够健康。"] = "Пусть Богиня защитит мою бедную маленькую Елену от беды и сохранит ее здоровье.",
    ["愿女神庇佑！"] = "Пусть Богиня защитит нас!",
    ["愿风暴与你同在。"] = "Да пребудет с тобой Буря.",
    ["愿风暴守护远航……"] = "Пусть Повелитель Штормов охраняет путешествие...",
    ["慈善性改善住房公司，让您住得安心，住得幸福！"] = "Благотворительная компания по улучшению жилищных условий: живите в уюте и спокойствии!",
    ["慈爱……天之母亲……"] = "Доброта... Матерь Небесная...",
    ["懂，这种事情我见多了。"] = "Я знаю, я видел много подобных вещей.",
    ["戈尔丁先生的鉴宝水平在贝克兰德最权威，他的眼光准没错。"] = "Навыки оценки г-на Голдинга являются самыми авторитетными в Баклунде, его взгляд никогда не ошибается.",
    ["成功的人生！就需要贝肯面包房的面包！"] = "Успешная жизнь! Для этого нужен хлеб из Baken Bakery!",
    ["我……"] = "Я...",
    ["我……我没醉……呕！"] = "Я... я не пьян... Ух!",
    ["我……我还是有点害怕……"] = "Я... мне все еще немного страшно...",
    ["我、我也还有力气！"] = "У... у меня тоже еще есть силы!",
    ["我、我做到了……我杀了他。"] = "Я-я сделал это... я убил его.",
    ["我、我可是尊贵的贝克兰德证券交易所交易员……"] = "Я, я выдающийся трейдер на Баклундской фондовой бирже...",
    ["我、我明白了女士……我什么都愿意做！"] = "Я, я понимаю, мэм... Я готов на все!",
    ["我、我的手该往哪里放？"] = "Куда, куда мне девать руки?",
    ["我一定会……找到你……"] = "Я обязательно... найду тебя...",
    ["我一定能做到的！"] = "Я определенно смогу это сделать!",
    ["我一直想当家庭女教师，但现在工作的薪水也很不错。"] = "Я всегда хотела быть гувернанткой, но и зарплата на моей нынешней работе неплохая.",
    ["我一直都有点怕队长，虽然他很和蔼，给我父亲的感觉，但不知为什么就是害怕。"] = "Я всегда немного боялся капитана. Хоть он и очень добрый и вызывает у меня отцовское чувство, мне почему-то просто страшно.",
    ["我上我也行！"] = "Я мог бы сделать лучше, чем это!",
    ["我不……不是……呕……"] = "Я не... не... тьфу...",
    ["我不仅要价公道，而且还会帮客人把东西搬到家里。"] = "У меня не только честные цены, но я ещё и помогаю покупателям донести вещи прямо до дома.",
    ["我不会在这里倒下！"] = "Я не упаду здесь!",
    ["我不听我不听……"] = "Я не слушаю, я не слушаю...",
    ["我不想再睡在街道和公园的长椅上……"] = "Я больше не хочу спать на улицах и на скамейках в парках…",
    ["我不能陪着我的小孙女去贝克兰德了，愿女神保佑丽娃。"] = "Я больше не могу сопровождать свою маленькую внучку в Бэкланд. Пусть Богиня благословит Риву.",
    ["我不要多，就两瓶，卖给我嘛！"] = "Мне не нужно много, только две бутылки, продайте мне их!",
    ["我不记得过去，我遗忘了那些发誓要铭记的人和事……"] = "Я не помню прошлого, я забыл тех людей и вещи, которые поклялся помнить...",
    ["我不需要“善良”，善良救不了托马斯，救不了艾玛，只会让我再次失去一切……"] = "Мне не нужна «доброта». Доброта не спасла Томаса, не спасла Эмму, она лишь снова лишит меня всего...",
    ["我也不知道，只是听她说是有人吃了那样美食，癫痫就好了。"] = "Я и сам толком не знаю, только слышал от нее, будто кто-то отведал этого лакомства и излечился от припадков.",
    ["我也不知道，或许只是这样远远看着她就够了……"] = "Не знаю, может, достаточно просто посмотреть на нее издалека...",
    ["我也在家里练习了很久，天天对着鸡蛋仔细观察。"] = "Я тоже долго тренировался дома, целыми днями пристально разглядывая куриные яйца.",
    ["我也想学习魔镜占卜。"] = "Еще я хочу научиться магическому зеркальному гаданию.",
    ["我也想寻宝！"] = "Я тоже хочу поискать сокровища!",
    ["我也想拥有薪水！"] = "Я тоже хочу зарплату!",
    ["我也拿不出一分钱……"] = "У меня тоже нет ни копейки...",
    ["我也是听别人讲的，信不信由你。"] = "Я просто рассказываю вам то, что слышал от других, хотите верьте, хотите нет.",
    ["我也有事想同你说！前面路口的地下垃圾桶里一直发出叹息和怪响！"] = "У меня тоже есть что сказать! В подземном мусорном баке на ближайшем перекрёстке всё время слышны вздохи и странные звуки!",
    ["我买一支送你，你和我回家好不好呀？"] = "Если я куплю его для тебя, ты пойдешь со мной домой?",
    ["我亲手开启的工业革命，亲手铸就的蒸汽与机械时代，将成为邪神降生的温床？"] = "Промышленная революция, которую я начал своими руками, эпоха пара и машин, которую я выковал сам, станут рассадником рождения Злого Бога?",
    ["我亲眼看到了幽灵，就在古堡旁边！"] = "Я видел привидение своими глазами, прямо возле старого замка!",
    ["我什么时候才能成为一名合格的占卜师呢……"] = "Когда я смогу стать квалифицированным гадателем...",
    ["我从她身边路过时闻到了香水味！你说她不会是在香水店做事的吧？"] = "Я почувствовала запах духов, когда проходила мимо нее! Думаешь, она работает в парфюмерном магазине?",
    ["我以后也要像他们一样当英雄，守卫国家，保护家人。"] = "Когда я вырасту, я хочу стать таким же героем, как они, защищать страну и свою семью.",
    ["我以女神的名义起誓，将付出一切维护此交易的合法与公平。"] = "Я клянусь именем Богини сделать все возможное, чтобы поддержать законность и справедливость этой сделки.",
    ["我们不能。"] = "Мы не можем.",
    ["我们为什么要在教堂旁边交易？你疯了吗？！"] = "Почему мы торгуем рядом с церковью? Вы с ума сошли? !",
    ["我们从佐特兰街到圣赛琳娜教堂，再沿豪尔斯街……"] = "Идем от Заутланд-стрит к собору Святой Селены, затем по Хаулс-стрит...",
    ["我们以苍白灾难为开始，东拜朗海战结尾……"] = "Мы начинаем с Бледной катастрофы и заканчиваем морским сражением за Восточный Балам...",
    ["我们会……夜空……"] = "Мы будем... ночное небо...",
    ["我们会抬头仰望那片夜空，"] = "Мы посмотрим на это ночное небо,",
    ["我们去索菲亚姐姐那买冰淇淋好吗？"] = "Пойдем к сестре Софии купить мороженого?",
    ["我们去问问其他人的价格。"] = "Давайте спросим у других цены.",
    ["我们向队长承诺过，会照顾您的，就像自己的母亲一样！"] = "Мы обещали Капитану, что позаботимся о вас, как о собственной матери!",
    ["我们在等待戈多。"] = "Ждем Годо.",
    ["我们在迪西过的很好，孩子们很听话，您不用挂念。"] = "У нас в Диси дела идут очень хорошо, дети очень послушные, можете не волноваться.",
    ["我们多久没休假了？"] = "Сколько времени прошло с тех пор, как мы были в отпуске?",
    ["我们多么贫穷，穷到只剩下钱了！"] = "До чего же мы бедны — настолько бедны, что у нас остались только деньги!",
    ["我们很想念您，就带着孩子一起过来看您了。"] = "Мы очень скучали по вам, поэтому привели детей к вам.",
    ["我们很理解您的心情……"] = "Мы прекрасно понимаем, что вы чувствуете...",
    ["我们得快点找到那只猫，给它点食物吃。"] = "Нам нужно быстро найти этого кота и накормить его чем-нибудь.",
    ["我们得让廷根重新伟大起来！"] = "Мы должны снова сделать Тингена великим!",
    ["我们投票决定，下周由你代表小组进行课程汇报！"] = "Мы проголосовали за то, чтобы вы представляли группу на презентации курса на следующей неделе!",
    ["我们搬运沉重的货物，踩着肮脏的水，可这才每周2苏勒。"] = "Мы тащим тяжелые грузы и тащимся по грязной воде, но получаем за это всего 2 суле в неделю.",
    ["我们明明是“黑夜四兄妹”！让我们一起歌颂女神！"] = "Мы явно «Четыре брата и сестры ночи»! Давайте вместе прославим Богиню!",
    ["我们是弗萨克的士兵，我们要消散了，能不能请求你……"] = "Мы солдаты Фейсака, и мы вот-вот рассеемся... Можем ли мы попросить тебя...",
    ["我们是新成立的乐队“黑夜四姐弟”，请多多支持！"] = "Мы новая группа «Четверо братьев и сестер Ночи», поддержите нас!",
    ["我们有新鲜出炉的泥馅饼、泥蘑菇汤和泥冰茶！"] = "У нас есть свежеиспеченные грязевые пироги, суп из грязевых грибов и грязевой чай со льдом!",
    ["我们永远在刀尖上跳舞，却没发现脚下的幸运早就飘走啦。"] = "Мы всегда танцуем на острие ножа, так и не поняв, что удача под нашими ногами уже давно ускользнула.",
    ["我们的哭声在旋转的轮轴间回响……"] = "Наши крики эхом отражаются от вращающихся колес...",
    ["我们的藏书太少了……"] = "Наша коллекция книг слишком мала...",
    ["我们祈求您的眷顾，祈求您庇护您忠实的信徒。"] = "Мы молим о Вашем благоволении, молим о защите Ваших верных последователей.",
    ["我们要做一辈子的好朋友，永远、永远！"] = "Мы будем лучшими друзьями на всю жизнь, во веки веков!",
    ["我们要偷渡上船吗？老大，好刺激！"] = "Мы собираемся спрятаться на корабле? Босс, это так интересно!",
    ["我们走吧，还得下几层楼梯。"] = "Пойдём, нам ещё спускаться на несколько пролётов.",
    ["我们趁讲座堵住海默教授吧，我一定要他在我的书上签名！"] = "Давайте устроим засаду профессору Хамеру во время лекции, я должен заставить его подписать мою книгу!",
    ["我们这些哪能和他们在做的研究相比！"] = "Разве наши скромные труды сравнятся с исследованиями, которые ведут они!",
    ["我们这就去咖啡馆吧，今天露拉太太带来的红茶和点心真是不错……"] = "Пойдем в кафе. Черный чай и закуски, которые сегодня принесла госпожа Лула, просто чудесны...",
    ["我们都将开启新的人生，真是令人期待！"] = "Мы все собираемся начать новую жизнь, это действительно интересно!",
    ["我们都老了，风景却没有变化。当年咱们就是在这里逃的课。"] = "Мы оба состарились, но пейзаж не изменился. Здесь мы тогда прогуливали занятия.",
    ["我会一直想你的……"] = "Я всегда буду скучать по тебе...",
    ["我会保证这里的安全。"] = "Я обеспечу безопасность этого места.",
    ["我会尽我所能，为您打造一个宁静整洁的环境。"] = "Я сделаю все возможное, чтобы создать для вас тихую и опрятную обстановку.",
    ["我会想念你们的，我的朋友！"] = "Я буду скучать по вам всем, друзья мои!",
    ["我似乎的确听说过“波拿巴”这个名字，难道是真的吗？"] = "Кажется, я действительно слышал имя «Бонапарт», могло ли это быть правдой?",
    ["我保证这次绝对美味，让你再醒来时也能第一时间想起来！"] = "Уверяю, на этот раз выйдет потрясающе вкусно — даже когда снова очнешься, сразу же вспомнишь этот вкус!",
    ["我做不到，萨拉。"] = "Я не могу, Сара.",
    ["我其实另有偏好……"] = "Вообще-то у меня другие предпочтения...",
    ["我养的猎犬都比他耍得好！"] = "Моя охотничья собака сыграла бы лучше него!",
    ["我再也不要过这种被谎言和赌债填满的生活了！"] = "Я никогда не хочу снова прожить жизнь, наполненную ложью и карточными долгами!",
    ["我军队出身的父亲也会为我与会员们的交往感到自豪……"] = "Мой отец, служивший в армии, тоже гордился бы моим общением с членами клуба...",
    ["我决定同明斯特结婚了。"] = "Я решила выйти замуж за Мунстера.",
    ["我劝你最好不要去劳德家买海鲜，他卖的都是些臭鱼烂虾！"] = "Советую не покупать морепродукты у Лаудов; все, что он продает, — это тухлая рыба и креветки!",
    ["我去说她嫁的就是我了。"] = "Если бы я сказал это, она бы вместо этого вышла за меня замуж.",
    ["我又写了一首诗。"] = "Я написал еще одно стихотворение.",
    ["我又没做错什么，只是……算了，还是去道歉吧。"] = "Я не сделал ничего плохого, просто... забудь об этом, мне лучше пойти извиниться.",
    ["我受够你了！"] = "Ты мне надоел!",
    ["我只希望他能安稳长大，读完大学。"] = "Я лишь надеюсь, что он вырастет в безопасности и сможет окончить университет.",
    ["我只想要一瓶喷上去能让我更有勇气求婚的东西……"] = "Мне просто нужна бутылка, которая придаст мне больше смелости сделать предложение...",
    ["我只愿面朝大海，春暖花开……"] = "Я хочу только смотреть на море, на цветущие весенние цветы...",
    ["我只是一只鹦鹉，嘎。"] = "Я всего лишь попугай, каркай.",
    ["我只是想拥有一条自己的项链！！！"] = "Я просто хочу иметь собственное ожерелье!!!",
    ["我只是留不住那笔横财。"] = "Я просто не мог удержать эту неожиданную удачу.",
    ["我只是随便一说，你还当真了。"] = "Я просто сказал, что ты действительно отнесся к этому серьезно.",
    ["我只能出5便士……"] = "Могу предложить только 5 копеек...",
    ["我只能看出一点不协调，其他什么也发现不了。"] = "Я вижу только небольшое несоответствие, больше ничего не могу обнаружить.",
    ["我可不是去当游客，我要在那里立足，成为上等人。"] = "Я поеду туда не как турист. Я хочу обосноваться там и стать членом высшего класса.",
    ["我吃了二十年，也不觉得腻！"] = "Я ем их уже двадцать лет и никогда от них не устаю!",
    ["我向女神祈求安宁……祈求原谅……"] = "Я молю Богиню о мире... о прощении...",
    ["我听建议，每天都去教堂做弥撒，怎么还会梦见麦穗？"] = "Я последовала совету и каждый день ходила в церковь к мессе, так почему же мне до сих пор снятся колосья пшеницы?",
    ["我听说了，拜亚姆的天气就像天堂一样！"] = "Я слышал, что погода в Баяме просто рай!",
    ["我听说隔壁厂子引进了新设备，效率翻倍呢。"] = "Я слышал, что соседний завод внедрил новое оборудование, и его эффективность увеличилась вдвое.",
    ["我和那些大老板的关系很好，但那些说我们有私下交易的，全都是假新闻！"] = "У меня прекрасные отношения с этими большими боссами, но те, кто говорит, что у нас есть частные сделки, — это фейковые новости!",
    ["我和露西从小就是彼此最好的朋友。从我决定出海到现在，她已经等了我五年。"] = "Мы с Люси были лучшими друзьями друг друга с детства. С того момента, как я решил отправиться в плавание, и до сих пор, она ждала меня пять лет.",
    ["我哪有钱参与你们？我就看看。"] = "Откуда у меня были деньги, чтобы присоединиться к вам, ребята? Я просто посмотрю.",
    ["我喜欢能和我认真辩论历史观点的人。"] = "Мне нравятся люди, которые могут серьезно обсуждать со мной исторические точки зрения.",
    ["我喜欢酸梅糖，酸得眼泪都要流出来……但是吃完之后，嘴里会甜甜的，像先苦后甜的人生！"] = "Мне нравятся кислые сливовые конфеты; он настолько кислый, что у меня слезятся глаза... но после того, как я его съел, мой рот становится сладким, как жизнь, которая сначала горька, а потом сладка!",
    ["我喜欢阳光，温暖，让人感到内心平静。"] = "Мне нравится солнечный свет, он теплый и дает ощущение покоя внутри.",
    ["我在光明中起舞，我是你的烛火。"] = "Я танцую в сиянии света, я — пламя твоей свечи.",
    ["我在想，下次是不是可以试试加点水果风味……菠萝烤鱼怎么样？"] = "Вот думаю, может, в следующий раз добавить фруктовых ноток... Как насчет жареной рыбы с ананасами?",
    ["我在梦里见过这座古堡。 "] = "Этот древний замок я видел во сне.",
    ["我在等待“慷慨号”，驶向拜亚姆的船只！"] = "Я жду «Баунтифул», корабль, направляющийся в Баям!",
    ["我在红月下厮杀，我是你的影子。"] = "Я сражаюсь под красной луной, я твоя тень.",
    ["我在贝克兰德醒来时，随身携带了一个铜哨。"] = "Когда я проснулся в Баклунде, у меня с собой был медный свисток.",
    ["我太思念我的爱人布拉德利了，如果他能立刻出现在我面前就好了…"] = "Я так скучаю по своему возлюбленному Брэдли, если бы он только мог появиться передо мной прямо сейчас...",
    ["我好像……忘记了。"] = "Кажется, я... забыл.",
    ["我妻子还在家等我，没时间陪你耗下去了啊。"] = "Жена все еще ждет меня дома, у меня больше нет времени тратить время на тебя.",
    ["我姐姐卖完花就会回来做饭！要先喝点甜冰茶吗？"] = "Моя сестра вернется готовить после продажи цветов! Хотите сначала сладкого чая со льдом?",
    ["我完了，又睡过了……"] = "Мне конец, я снова проспал...",
    ["我家主人说，30镑是诚实者应得的报酬。"] = "Мой хозяин говорит, что 30 фунтов — это награда, которую заслуживает честный человек.",
    ["我对新党那些激进的工厂改革提议感到担忧。"] = "Меня беспокоят радикальные предложения по реформе фабрик со стороны Новой партии.",
    ["我将以献祭的方式将这封信寄给你。"] = "Я отправлю тебе это письмо через ритуал жертвоприношения.",
    ["我就不了，我要先送新人去入职，队长还等着呢。"] = "Я пас, мне нужно сначала отвезти новичка на дежурство, капитан еще ждет.",
    ["我就是来告诉您这些的。等下次我会给您带一束向日葵。"] = "Я просто пришел сказать тебе это. В следующий раз я принесу тебе букет подсолнухов.",
    ["我就是看看——克洛，救命啊！！"] = "Я просто смотрю - Ворона, помоги!!",
    ["我就是要加入“家庭仆人协会”！我就要工作！"] = "Я просто хочу присоединиться к «Ассоциации домашней прислуги»! Я просто хочу работать!",
    ["我就是试试大小，试试大小……哎呀卡住了！"] = "Я просто тестирую размер, тестирую размер... Упс, застряло!",
    ["我就能早日坐上私人马车，也能尽情环游世界了。"] = "Тогда я мог бы позволить себе частный экипаж раньше и путешествовать по миру в свое удовольствие.",
    ["我就说别来这种乡下地方待一周！太无聊了！"] = "Я же говорил: не надо было ехать в эту глушь на целую неделю! Скука смертная!",
    ["我已经三天三夜没有合眼，只为多看您一眼！"] = "Я не смыкал глаз три дня и три ночи, лишь бы еще хоть разок увидеть вас!",
    ["我已经全押在豪斯身上了，听说它有凛冬郡猎犬的血脉！"] = "Я ставлю олл-ин на Хауса, я слышал, в нем течет кровь Винтерширской гончей!",
    ["我已经尽力为穷苦的人们创造了更好的工作和生活环境。"] = "Я изо всех сил старался создать лучшие условия труда и жизни для бедных.",
    ["我已经道歉了三个小时了，能见见我吗，骂我一句也好啊！"] = "Я извиняюсь уже три часа, ты меня видишь? Даже если ты меня просто отругаешь!",
    ["我帮你，我记得它的位置。"] = "Я тебе помогу, я помню его местоположение.",
    ["我应该是付出了某些代价，才获得了漫长的生命，从第四纪的尾声一直活到现在，就像一个游荡于大陆各处的幽灵……"] = "Должно быть, я заплатил какую-то цену за то, чтобы прожить такую ​​долгую жизнь, живя с конца Четвертой Эпохи до сих пор, словно призрак, блуждающий по континенту...",
    ["我建议你不如先来吃块蛋糕，让脑子放松下。"] = "Я предлагаю вам сначала съесть кусок торта, чтобы дать мозгу расслабиться.",
    ["我很感谢曾经的雇主，他让我自由安排业余时间。"] = "Я очень благодарен своему бывшему работодателю; он позволил мне свободно организовывать свое свободное время.",
    ["我很难过……不对，我很高兴。"] = "Мне так грустно... нет, я так счастлива.",
    ["我得先去银冠餐厅狠狠消费一顿！"] = "Сначала мне нужно пойти в ресторан «Серебряная Корона» и потратить целое состояние!",
    ["我得去看看那群人有没有浪费我的水了。"] = "Мне нужно пойти проверить, не зря ли эта группа людей потратила мою воду.",
    ["我怀疑这本笔记是具备一定生命和智慧的邪恶物品。"] = "Я подозреваю, что этот дневник — зловещий предмет, наделённый зачатками жизни и разума.",
    ["我怎么沦落到要和这些下等民一起挤那东西了？"] = "Как я докатился до того, что вынужден тесниться в этой штуковине вместе с плебеями?",
    ["我总是听到一些温柔的说话声，但周围却空无一人。"] = "Я всегда слышу какие-то нежные голоса, но вокруг никого.",
    ["我想好了，先聊天气，再聊上次的音乐会，然后慢慢引入……"] = "Я решила, сначала расскажу о погоде, потом о прошедшем концерте, а потом потихоньку представлю...",
    ["我想明天应该去乔西亚太太的居所做一次半正式的拜访，刚好我有一件新的散步服。"] = "Думаю, завтра мне следует нанести полуофициальный визит в резиденцию миссис Джозайи; У меня случайно есть новый прогулочный костюм.",
    ["我想看到完美的滑行，所有桨叶离开水面！"] = "Я хочу видеть идеальное скольжение, выход всех весел из воды!",
    ["我想看机械飞船！"] = "Я хочу увидеть механические дирижабли!",
    ["我想给二位讲一讲我们大学的特色活动，赛艇……"] = "Хочу рассказать вам о знаковом мероприятии нашего университета – гребле...",
    ["我想让爸爸陪我玩了……"] = "Я хочу, чтобы папа поиграл со мной...",
    ["我想这种零食会大卖吧……"] = "Думаю, эта закуска будет хорошо продаваться...",
    ["我感觉下面凉飕飕的，不知道你那边是不是也这样。"] = "Я чувствую там холодок, интересно, у тебя то же самое?",
    ["我感觉好多了，母亲，我们现在就过去吧。"] = "Я чувствую себя намного лучше, мама, пойдем.",
    ["我感觉我一直活在罗塞尔大帝的影子里。"] = "У меня такое чувство, будто я всегда жил в тени императора Розеллы.",
    ["我懂你，兄弟！压力需要像气球一样被释放！"] = "Я понимаю тебя, брат! Стресс нужно выпускать, как воздушный шарик!",
    ["我我我，我要听风暴之主的神话！"] = "Я, я, я хочу услышать мифы о Повелителе бурь!",
    ["我才是廷根最时尚的人！"] = "Я самый модный человек в Тингене!",
    ["我才是您最忠诚的奴仆！"] = "Я твой самый верный слуга!",
    ["我打算找一堆侦探帮我查查是怎么回事……"] = "Я планирую найти группу детективов, которые помогут мне расследовать происходящее...",
    ["我把孩子送去了周日免费学校，希望他将来能和我不一样。"] = "Я отдал ребёнка в бесплатную воскресную школу. Надеюсь, его будущее будет не таким, как у меня.",
    ["我报考了历史系——廷根历史系是鲁恩最好的。"] = "Я подал заявление на исторический факультет — исторический факультет Тингена лучший в Лоене.",
    ["我擦个鼻涕还得把纸带回家里扔吗？"] = "Мне что, нужно уносить бумагу домой, чтобы выбросить, если я просто вытер нос?",
    ["我敢保证没人能学会弹奏乐器！"] = "Я гарантирую, что никто никогда не научится играть на музыкальном инструменте!",
    ["我敢出1便士打赌，二副不会为他出这笔钱。"] = "Ставлю 1 пенс, что второй помощник не заплатит за него этих денег.",
    ["我是……嗝，我是个失败的父亲……"] = "Я... *ик*, я неудавшийся отец...",
    ["我是一朵蘑菇，我不会饿……"] = "Я гриб, я не голоден...",
    ["我是不是该去换一个发型？"] = "Может, мне стоит сменить прическу?",
    ["我是你二大爷"] = "Я твой двоюродный дедушка.",
    ["我是你二大爷啊"] = "Я правда твой двоюродный дедушка.",
